logger = logging.getLogger("desktopenv.metrics.audacity")


def _read_wav_info(file_path):
    """Read basic WAV info using the stdlib wave module. Returns dict with
    'channels', 'sample_rate', 'n_frames', 'duration', 'sampwidth'."""
    with wave.open(file_path, "rb") as wf:
        channels = wf.getnchannels()
        sample_rate = wf.getframerate()
        n_frames = wf.getnframes()
        sampwidth = wf.getsampwidth()
        duration = n_frames / sample_rate if sample_rate > 0 else 0.0
        return {
            "channels": channels,
            "sample_rate": sample_rate,
            "n_frames": n_frames,
            "duration": duration,
            "sampwidth": sampwidth,
        }


def _read_wav_samples(file_path):
    """Read WAV samples as floats in [-1.0, 1.0], preserving interleaving."""
    with wave.open(file_path, "rb") as wf:
        n_frames = wf.getnframes()
        channels = wf.getnchannels()
        sampwidth = wf.getsampwidth()
        raw = wf.readframes(n_frames)

    total_samples = n_frames * channels
    if sampwidth == 1:
        samples = struct.unpack(f"{total_samples}B", raw)
        return [(s - 128) / 128.0 for s in samples]
    if sampwidth == 2:
        samples = struct.unpack(f"<{total_samples}h", raw)
        return [s / 32768.0 for s in samples]
    if sampwidth == 3:
        result = []
        for i in range(total_samples):
            b = raw[i * 3: i * 3 + 3]
            val = int.from_bytes(b, byteorder="little", signed=True)
            result.append(val / 8388608.0)
        return result
    if sampwidth == 4:
        samples = struct.unpack(f"<{total_samples}i", raw)
        return [s / 2147483648.0 for s in samples]
    raise ValueError(f"Unsupported sample width: {sampwidth}")


def _get_mono_samples(file_path):
    info = _read_wav_info(file_path)
    samples = _read_wav_samples(file_path)
    channels = info["channels"]
    if channels > 1:
        mono = []
        for i in range(0, len(samples), channels):
            mono.append(sum(samples[i:i + channels]) / channels)
        return mono, info["sample_rate"]
    return samples, info["sample_rate"]


def _resolve_reference_path(path):
    """Resolve repo asset paths when evaluator runs from repo root or task dir."""
    if os.path.isabs(path) and os.path.isfile(path):
        return path

    candidates = [
        os.path.abspath(path),
        os.path.join(os.path.dirname(__file__), path),
    ]

    base = os.path.dirname(__file__)
    for _ in range(8):
        candidates.append(os.path.join(base, path))
        base = os.path.dirname(base)

    for candidate in candidates:
        if os.path.isfile(candidate):
            return candidate
    return path


def _pearson_corr(a, b):
    if not a or not b:
        return 0.0
    n = min(len(a), len(b))
    a = a[:n]
    b = b[:n]
    mean_a = sum(a) / n
    mean_b = sum(b) / n
    num = sum((x - mean_a) * (y - mean_b) for x, y in zip(a, b))
    den_a = math.sqrt(sum((x - mean_a) ** 2 for x in a))
    den_b = math.sqrt(sum((y - mean_b) ** 2 for y in b))
    if den_a < 1e-12 or den_b < 1e-12:
        return 0.0
    return num / (den_a * den_b)


def _rms_linear(samples):
    if not samples:
        return 0.0
    return math.sqrt(sum(s * s for s in samples) / len(samples))


def check_audio_duration(file_path, rule) -> float:
    """Check audio file duration.
    rule: {"expected_duration": float, "tolerance": float (default 0.5)}
    """
    try:
        if not os.path.isfile(file_path):
            logger.error(f"File not found: {file_path}")
            return 0.0
        info = _read_wav_info(file_path)
        expected = float(rule["expected_duration"])
        tolerance = float(rule.get("tolerance", 0.5))
        actual = info["duration"]
        logger.info(f"check_audio_duration: actual={actual:.2f}s, expected={expected:.2f}s, tol={tolerance:.2f}s")
        if abs(actual - expected) <= tolerance:
            return 1.0
        return 0.0
    except Exception as e:
        logger.error(f"check_audio_duration error: {e}")
        return 0.0


def check_audio_double_delete_content(file_path, rule) -> float:
    """Verify output equals source after deleting two specified timeline ranges.

    The delete ranges are applied sequentially, so the second range is on the
    current timeline after the first deletion.

    rule: {
        "source_path": str,
        "delete_ranges": [[start, end], ...],
        "expected_duration": float,
        "tolerance": float (default 0.5),
        "correlation_threshold": float (default 0.98),
        "max_normalized_rmse": float (default 0.08)
    }
    """
    try:
        if not os.path.isfile(file_path):
            logger.error(f"Output file not found: {file_path}")
            return 0.0

        source_path = _resolve_reference_path(rule["source_path"])
        if not os.path.isfile(source_path):
            logger.error(f"Source reference file not found: {source_path}")
            return 0.0

        output_info = _read_wav_info(file_path)
        expected_duration = float(rule["expected_duration"])
        tolerance = float(rule.get("tolerance", 0.5))
        if abs(output_info["duration"] - expected_duration) > tolerance:
            logger.info(
                f"Duration mismatch: output={output_info['duration']:.2f}s, "
                f"expected={expected_duration:.2f}s"
            )
            return 0.0

        source_samples, source_sr = _get_mono_samples(source_path)
        output_samples, output_sr = _get_mono_samples(file_path)
        if source_sr != output_sr:
            logger.info(f"Sample rate mismatch: source={source_sr}, output={output_sr}")
            return 0.0

        expected = source_samples[:]
        for start, end in rule["delete_ranges"]:
            start_idx = int(float(start) * source_sr)
            end_idx = int(float(end) * source_sr)
            start_idx = max(0, min(start_idx, len(expected)))
            end_idx = max(0, min(end_idx, len(expected)))
            if end_idx <= start_idx:
                logger.error(f"Invalid delete range: {start}-{end}")
                return 0.0
            expected = expected[:start_idx] + expected[end_idx:]

        n = min(len(output_samples), len(expected))
        if n < 1:
            return 0.0

        actual = output_samples[:n]
        expected = expected[:n]
        corr = _pearson_corr(actual, expected)
        rmse = math.sqrt(sum((a - e) ** 2 for a, e in zip(actual, expected)) / n)
        normalized_rmse = rmse / max(_rms_linear(expected), 1e-9)
        corr_threshold = float(rule.get("correlation_threshold", 0.98))
        max_nrmse = float(rule.get("max_normalized_rmse", 0.08))

        logger.info(
            f"check_audio_double_delete_content: corr={corr:.4f}, "
            f"normalized_rmse={normalized_rmse:.4f}"
        )

        if corr < corr_threshold:
            return 0.0
        if normalized_rmse > max_nrmse:
            return 0.0
        return 1.0
    except Exception as e:
        logger.error(f"check_audio_double_delete_content error: {e}")
        return 0.0
